#initial{position:absolute;left:0;top:510px;width:1280px;text-align:center;font-size:32px;line-height:48px;opacity:0}
.trade-label{position:absolute;font-size:27px;font-weight:700;line-height:42px;white-space:nowrap;opacity:0}#buy-label{left:559px;top:426px;color:#175DB5}#sell-label{left:942px;top:151px;color:#A94A19}
#holding{position:absolute;left:564px;top:506px;width:132px;height:56px;opacity:0}#holding svg{width:132px;height:56px}#holding span{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:28px;line-height:40px;color:#175DB5}
#formula,#final-state,#risk{position:absolute;left:80px;width:1120px;text-align:center;margin:0;opacity:0;white-space:nowrap}#formula{top:478px;font-size:36px;line-height:52px;font-weight:700}#final-state{top:534px;font-size:30px;line-height:44px}#risk{top:585px;font-size:28px;line-height:40px;font-weight:700}.buy{color:#175DB5}.sell{color:#A94A19}
