tl.to('#active-point',{attr:{cx:630,cy:400},duration:2,ease:'none'},5);
tl.set('#active-point',{attr:{opacity:0}},7);
tl.fromTo('#buy-ring',{attr:{r:9,opacity:0.8}},{attr:{r:24,opacity:0},duration:0.55,ease:'power1.out'},7);
tl.to('#buy-event',{attr:{opacity:1},duration:0.2},7.06);
tl.fromTo('#buy-heading',{opacity:0,y:6},{opacity:1,y:0,duration:0.3},7.08);
tl.fromTo('#buy-label',{opacity:0,y:5},{opacity:1,y:0,duration:0.3},7.12);
tl.fromTo('#holding',{opacity:0,y:8,x:0},{opacity:1,y:0,x:0,duration:0.35,ease:'power1.out'},7.55);
tl.to('#buy-heading',{opacity:0,duration:0.25},11);
tl.set('#up-path',{attr:{opacity:1}},11);
tl.set('#active-point',{attr:{opacity:1}},11);
tl.to('#up-path',{attr:{x2:1020,y2:220},duration:2,ease:'none'},11);
tl.to('#active-point',{attr:{cx:1020,cy:220},duration:2,ease:'none'},11);
tl.set('#active-point',{attr:{opacity:0}},13);
tl.to('#sell-event',{attr:{opacity:1},duration:0.2},13.06);
tl.fromTo('#sell-heading',{opacity:0,y:6},{opacity:1,y:0,duration:0.3},13.08);
tl.fromTo('#sell-label',{opacity:0,y:5},{opacity:1,y:0,duration:0.3},13.12);
tl.to('#holding',{x:390,y:-226,duration:0.8,ease:'power1.inOut'},13.5);
tl.to('#holding',{opacity:0,duration:0.25},14.3);
tl.to('#sell-heading',{opacity:0,duration:0.2},17);
tl.to('#result-title',{opacity:1,duration:0.25},17.2);
tl.fromTo('#formula',{opacity:0,y:6},{opacity:1,y:0,duration:0.35},17.05);
tl.fromTo('#final-state',{opacity:0,y:6},{opacity:1,y:0,duration:0.3},17.35);
tl.fromTo('#risk',{opacity:0,y:6},{opacity:1,y:0,duration:0.3},17.7);
