      {"kind": "appearsBy", "selector": "#final-state", "bySec": 18},
      {"kind": "appearsBy", "selector": "#risk", "bySec": 18},
      {"kind": "appearsBy", "selector": "#footer", "bySec": 0},
      {"kind": "staysInFrame", "selector": "#holding"},
      {"kind": "staysInFrame", "selector": "#formula"},
